create extension if not exists pgcrypto;
create table if not exists admin_users (id uuid primary key default gen_random_uuid(),name text not null,email text not null unique,password_hash text not null,role text not null default 'super_admin',status text not null default 'active',last_login_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists membership_applications (id uuid primary key default gen_random_uuid(),bisa_id text unique not null,application_status text not null default 'Submitted',payment_status text not null default 'Unpaid',name_en text not null,name_bn text,father_name text,mother_name text,date_of_birth text,gender text,blood_group text,national_id text,mobile text not null,email text not null,present_division text,present_district text,present_upazila text,present_post_office text,present_address text,permanent_division text,permanent_district text,permanent_upazila text,permanent_post_office text,permanent_address text,recruitment_rule text,organization_level text,ministry text,directorate text,office text,current_office_name text,current_designation text not null,joining_designation text,service_type text,service_employee_id text,joining_date text,batch_recruitment_year text,ict_experience_years text,current_grade text,current_pay_scale text,current_posting_division text,current_posting_district text,current_posting_upazila text,current_posting_location_summary text,expertise_areas text,expertise_area_other text,highest_degree text,institution_name text,subject_discipline text,passing_year text,result text,professional_certifications text,membership_type text not null,declaration_accepted boolean not null default false,declaration_accepted_at timestamptz,admin_note text,rejection_reason text,reviewed_by uuid,reviewed_at timestamptz,approved_at timestamptz,rejected_at timestamptz,submitted_at timestamptz default now(),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists bisa_id_counters(year integer primary key,last_number integer not null default 0,updated_at timestamptz default now());
create table if not exists application_audit_logs(id uuid primary key default gen_random_uuid(),application_id uuid references membership_applications(id) on delete cascade,action text not null,description text,actor_id uuid,actor_name text,created_at timestamptz default now());
create or replace function generate_next_bisa_id() returns text language plpgsql as $$ declare y integer:=extract(year from now()); c integer:=0; m integer:=0; n integer; begin insert into bisa_id_counters(year,last_number) values(y,0) on conflict(year) do nothing; select last_number into c from bisa_id_counters where year=y for update; select coalesce(max((regexp_replace(bisa_id,'^BISA-\d{4}-(\d+)$','\1'))::integer),0) into m from membership_applications where bisa_id like 'BISA-'||y||'-%'; n:=greatest(c,m)+1; update bisa_id_counters set last_number=n,updated_at=now() where year=y; return 'BISA-'||y||'-'||lpad(n::text,6,'0'); end $$;
